<h4>THE HUTCHINSONS' KANSAS SUFFRAGE SONG.</h4>

<h5>WORDS BY P. P. FOWLER AND J. W. H.</h5>

<p>As sung at the meetings and concerts during ther grand campaign on the
suffrage issue the season of 1867 in Kansas, and at the polls in
Leavenworth, by the Tribe of John, on the day of election.</p>

<div class="poem"><div class="stanza">
<span class="i0">O, say what thrilling songs of fairies,<br /></span>
<span class="i0">Wafted o'er the Kansas prairies,<br /></span>
<span class="i0">Charm the ear while zephyrs speed 'em!<br /></span>
<span class="i0">Woman's pleading for her freedom.<br /></span>
</div><div class="stanza">
<span class="i4"><span class="smcap">Chorus</span>&mdash;Clear the way, the songs are floating;<br /></span>
<span class="i8">Clear the way, the world is noting;<br /></span>
<span class="i8">Prepare the way, the right promoting,<br /></span>
<span class="i8">And ballots, too, for woman's voting.<br /></span>
</div><div class="stanza">
<span class="i0">We frankly say to fathers, brothers,<br /></span>
<span class="i0">Husbands, too, and several others,<br /></span>
<span class="i0">We're bound to win our right of voting,<br /></span>
<span class="i0">Don't you hear the music floating?<br /></span>
</div><div class="stanza">
<span class="i0">We come to take with you our station,<br /></span>
<span class="i0">Brave defenders of the nation,<br /></span>
<span class="i0">And aim by noble, just endeavor<br /></span>
<span class="i0">To elevate our sex forever.<br /></span>
</div><div class="stanza">
<span class="i0">By this vote we'll rid our nation<br /></span>
<span class="i0">Of its vile intoxication.<br /></span>
<span class="i0">Can't get rum? Oh, what a pity!<br /></span>
<span class="i0"><i>Dram-shops</i> closed in every city.<br /></span>
</div><div class="stanza">
<span class="i0">Fear not, we'll darn each worthy stocking,<br /></span>
<span class="i0">Duly keep the cradle rocking,<br /></span>
